 "content": "def transform(grid):
    """Extend colored diagonal runs along their direction to the grid edge."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Find maximal diagonal runs (length >= 2) and extend their endpoints.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue  # not the beginning of a maximal run
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                # Extend both directions, stopping at the boundary or a different object.
                for sr, sc, step_r, step_c in ((run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                                                (run[-1][0] + dr, run[-1][1] + dc, dr, dc)):
                    while 0 <= sr < h and 0 <= sc < w:
                        if grid[sr][sc] != bg and grid[sr][sc] != color:
                            break
                        out[sr][sc] = color
                        sr += step_r
                        sc += step_c
    return out

